import ast
import sys
for path in sys.argv[1:]:
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float) and node.value not in (0, 1):
            print(path, "numeric literal", node.value, node.lineno)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store) and len(node.id) < 4:
            print(path, "short name", node.id, node.lineno)
        if isinstance(node, ast.arg) and len(node.arg) < 4:
            print(path, "short arg", node.arg, node.lineno)
        if isinstance(node, ast.ImportFrom):
            print(path, "from-import", node.lineno)
        if isinstance(node, ast.FunctionDef):
            span = node.end_lineno - node.lineno + 1
            if span > 8:
                print(path, "long function", node.name, span)
        if isinstance(node, ast.Attribute) and node.attr.startswith("assert") and node.attr not in ("assertTrue", "assertFalse", "assertRaises"):
            print(path, "disallowed assert", node.attr, node.lineno)
    names = [n.lineno for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    print(path, "import lines:", names)
print("done")
