# owner: platform
import typing
import rosterkit.models as models

COLUMN_GAP = "  "


def require_email(item: models.Student) -> None:
    """Raise ValueError naming the student when no email is on file."""
    if not (item.email or "").strip():
        text = f"no email on file for {item.display_name}"
        raise ValueError(f"{text} (id {item.student_id})")


def check_roster(roster: typing.List[models.Student]) -> None:
    """Refuse an empty roster, then any student without an email."""
    if not roster:
        raise ValueError("no students to build a contact sheet from")
    for item in roster:
        require_email(item)


def pad_column(cells: typing.List[str]) -> typing.List[str]:
    """Left-justify every cell to the width of the widest one."""
    width = max(len(cell) for cell in cells)
    return [cell.ljust(width) for cell in cells]


def align_rows(roster: typing.List[models.Student]) -> typing.List[str]:
    """Pad the name and section columns so the emails line up."""
    names = pad_column([item.display_name for item in roster])
    sections = pad_column([item.section for item in roster])
    return [
        f"{name}{COLUMN_GAP}{section}{COLUMN_GAP}{item.email}"
        for name, section, item in zip(names, sections, roster)
    ]


def contact_rows(
    students: typing.Iterable[models.Student]
) -> typing.List[str]:
    """Aligned name, section and email lines, sorted by name."""
    roster = sorted(students, key=lambda item: item.display_name)
    check_roster(roster)
    return align_rows(roster)
